UPDATE public.questions AS t
   SET original_question_text = COALESCE(t.original_question_text, t.question_text),
       original_correct_answer = COALESCE(t.original_correct_answer, t.correct_answer),
       original_incorrect_answers = COALESCE(t.original_incorrect_answers, t.incorrect_answers),
       question_text = v.stem,
       correct_answer = v.correct,
       incorrect_answers = v.wrong,
       shorten_status = 'shortened'
  FROM (VALUES
    ('010ff21e', 'Which cancer is caused almost exclusively by asbestos?', 'Mesothelioma', '["Acute radiation syndrome", "Type 1 Diabetes", "Bacterial meningitis"]'::jsonb),
    ('03183e9c', 'What is drawing the frames between two key poses called?', 'In-betweening', '["Keyframing", "Storyboarding", "Post-production"]'::jsonb),
    ('05480ffb', 'What did Japan''s Sakoku isolation policy do to its economy?', 'Made it self-sufficient', '["Caused widespread famine", "Sped industrialization", "Collapsed the currency"]'::jsonb),
