    ('05d8f0bc', 'In which country was umami first identified as a basic taste?', 'Japan', '["China", "Thailand", "Vietnam"]'::jsonb),
    ('069f604c', 'Which Fertile Crescent grain became the first leavened bread?', 'Wheat', '["Barley", "Rice", "Potato"]'::jsonb),
    ('06e843cb', 'Which outer planet got the most expensive robotic mission?', 'Saturn', '["Neptune", "Uranus", "Jupiter"]'::jsonb),
    ('0abb8e56', 'Which manga has won the most Eisner Awards in English?', 'Akira', '["Lone Wolf and Cub", "Ghost in the Shell", "Naruto"]'::jsonb),
    ('0bac04ea', 'Which dockless commuter vehicle boomed in the late 2010s?', 'Electric Scooters', '["E-Bikes", "E-Skateboards", "Segways"]'::jsonb),
    ('0e3c48f7', 'Which ad format implies a dramatic transformation?', 'Before and after', '["Progress logs", "Duration disclaimers", "Video testimonials"]'::jsonb),
    ('0f5ec842', 'What does Occam''s Razor say to prefer in an explanation?', 'The fewest assumptions', '["The most evidence", "The most complexity", "The most predictions"]'::jsonb),
    ('1633c4a8', 'Which labourer''s workwear became a global fashion staple?', 'Blue jeans', '["Trench coat", "Flannel shirt", "Leather jacket"]'::jsonb),
    ('18d63d45', 'Which rating scale is standard in anxiety questionnaires?', 'Likert scale', '["Binary classification", "Categorical ranking", "Visual analog scale"]'::jsonb),
    ('1f2dd728', 'Which site is a meme punchline for diagnosing you with cancer?', 'WebMD', '["Wikipedia", "Google Maps", "Facebook"]'::jsonb),
    ('1fc1be05', 'Which algorithm finds the shortest path in a weighted graph?', 'A* search', '["Bubble sort", "Hash function", "Memory manager"]'::jsonb),
    ('24d2b3a6', 'Which phone was recalled in 2016 for catching fire?', 'Galaxy Note 7', '["iPhone 6 Plus", "Nexus 6P", "OnePlus 2"]'::jsonb),
    ('2a0b6cbf', 'Which encryption standard did NIST adopt in 2001?', 'AES', '["RSA", "DES", "Elliptic curve"]'::jsonb),
    ('2decccf0', 'In which game series does Link quest to save Hyrule?', 'The Legend of Zelda', '["Final Fantasy", "The Elder Scrolls", "Grand Theft Auto"]'::jsonb),
    ('2f8c00fd', 'In what year did CERN put the World Wide Web in the public domain?', '1993', '["1989", "1991", "1995"]'::jsonb),
    ('3047ded9', 'Who won the 1938 Physics Nobel for induced radioactivity?', 'Enrico Fermi', '["Ernest Rutherford", "Marie Curie", "Leo Szilard"]'::jsonb),
    ('347461e2', 'Where and when did Jenner first vaccinate against smallpox?', 'England, 1796', '["France, 1803", "United States, 1789", "Germany, 1775"]'::jsonb),
    ('398a33c9', 'In which decade was humanistic psychology''s association founded?', '1960s', '["1940s", "1950s", "1970s"]'::jsonb),
